// ---- EDIT THIS CONFIG ----
const CONFIG = {
  jobId: 'orders-history-2020-2024',
  // Source API
  baseUrl: 'https://api.example.com/v1/orders',
  method: 'GET',
  headers: {
    'Authorization': 'Bearer YOUR_TOKEN_HERE',
    'Accept': 'application/json'
  },
  // Checkpoint strategy: 'cursor' | 'date' | 'id'
  checkpointType: 'date',
  checkpointParam: 'start_date',   // query param name
  endParam: 'end_date',
  limitParam: 'limit',
  limit: 200,
  dataPath: 'data',                // where the array lives in the response
  nextCheckpointPath: 'meta.next_date', // optional path for next value
  // Date range (used when checkpointType = date)
  startDate: '2020-01-01',
  endDate: '2024-12-31',
  // Safety
  maxBatchesPerRun: 50,
  // Target table
  targetTable: 'orders_history',
  uniqueKey: 'order_id',
  fieldMap: {
    id: 'order_id',
    customer_id: 'customer_id',
    amount: 'amount',
    created_at: 'created_at'
  }
};

// Try to read existing progress (the Ensure node does not return rows, so we start fresh if missing)
let checkpoint = CONFIG.startDate;
let batchesDone = 0;
let recordsDone = 0;
let status = 'running';

return [{
  json: {
    config: CONFIG,
    state: {
      checkpoint,
      batchesDone,
      recordsDone,
      status,
      batchesThisRun: 0,
      hasMore: true
    },
    request: {
      url: CONFIG.baseUrl,
      qs: {
        [CONFIG.limitParam]: CONFIG.limit,
        [CONFIG.checkpointParam]: checkpoint,
        [CONFIG.endParam]: CONFIG.endDate
      }
    }
  }
}];

function ref(name) {
  try { return $(name).item.json; } catch (e) { return $(name).first().json; }
}
const prev = ref('Code - Load Config & Checkpoint');
const cfg = prev.config;
const state = { ...prev.state };
const res = $input.first().json;

const statusCode = Number(res.statusCode) || 0;
let body = res.body;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) { body = {}; }
}

function getPath(obj, path) {
  if (!path) return obj;
  return path.split('.').reduce((o, k) => (o && o[k] !== undefined ? o[k] : null), obj);
}

let records = getPath(body, cfg.dataPath) || [];
if (!Array.isArray(records)) records = [];

// Normalize
const normalized = records.map(r => {
  const row = {};
  for (const [src, dest] of Object.entries(cfg.fieldMap)) {
    row[dest] = r[src] !== undefined ? r[src] : null;
  }
  return row;
});

// Decide next checkpoint
let nextCheckpoint = state.checkpoint;
if (cfg.checkpointType === 'date' && normalized.length > 0) {
  // Use the last record's date or the path if provided
  const fromPath = getPath(body, cfg.nextCheckpointPath);
  if (fromPath) {
    nextCheckpoint = fromPath;
  } else {
    const last = normalized[normalized.length - 1];
    nextCheckpoint = last.created_at || last.order_date || state.checkpoint;
  }
} else if (cfg.checkpointType === 'cursor') {
  nextCheckpoint = getPath(body, cfg.nextCheckpointPath) || null;
} else if (cfg.checkpointType === 'id' && normalized.length > 0) {
  nextCheckpoint = String(normalized[normalized.length - 1][cfg.uniqueKey]);
}

const hasMore = normalized.length >= cfg.limit && state.batchesThisRun + 1 < cfg.maxBatchesPerRun;

return [{
  json: {
    config: cfg,
    state: {
      ...state,
      nextCheckpoint,
      hasMore
    },
    records: normalized,
    httpStatus: statusCode,
    success: statusCode >= 200 && statusCode < 300
  }
}];

