{{ (() => {
  const cfg = $json.config;
  const rows = $json.records;
  if (!rows || !rows.length) return 'SELECT 1';
  const cols = Object.values(cfg.fieldMap);
  const unique = cfg.uniqueKey;
  const values = rows.map(r => {
    const vals = cols.map(c => {
      const v = r[c];
      if (v === null || v === undefined) return 'NULL';
      if (typeof v === 'number') return v;
      return "'" + String(v).replace(/'/g, "''") + "'";
    });
    return '(' + vals.join(',') + ')';
  }).join(',\n');
  const updateSet = cols.filter(c => c !== unique).map(c => c + ' = EXCLUDED.' + c).join(', ');
  return `INSERT INTO ${cfg.targetTable} (${cols.join(',')})\nVALUES\n${values}\nON CONFLICT (${unique}) DO UPDATE SET ${updateSet};`;
})() }}

