function ref(name) {
  try { return $(name).item.json; } catch (e) { return $(name).first().json; }
}
const parsed = ref('Code - Normalize & Validate Batch');
const cfg = parsed.config;
const state = parsed.state;
const recordCount = (parsed.records || []).length;

const newState = {
  ...state,
  checkpoint: state.nextCheckpoint,
  batchesDone: (state.batchesDone || 0) + 1,
  recordsDone: (state.recordsDone || 0) + recordCount,
  batchesThisRun: (state.batchesThisRun || 0) + 1,
  hasMore: state.hasMore
};

return [{
  json: {
    config: cfg,
    state: newState,
    request: {
      url: cfg.baseUrl,
      qs: {
        [cfg.limitParam]: cfg.limit,
        [cfg.checkpointParam]: newState.checkpoint,
        [cfg.endParam]: cfg.endDate
      }
    },
    shouldContinue: newState.hasMore === true
  }
}];

